.alias TESTSW            $4300    ;TEST SWITCH DIRECT INPUT
.alias DIAGSW            $4320    ;Port with the diagnostic switch (bit DIAGBT of R_BYT1).
.alias IN1               $4320    ;R_BYT1 under its other name; the self test reads the thumb switches here.
.alias M_BUSY            $4320    ;D7 SET ==> RUNNING
.alias R_BYT1            $4320    ;Read: switch byte 1. D7 math box running, D6 VG halted, D5 left thumb, D4 right thumb, D3 spare 2, D2 diagnostic step; D1, D0 unused. Switches active low.
.alias VGHALT            $4320    ;D6 ON=> HALTED, ELSE RUNNING (HUNG?)
.alias R_BYT2            $4340    ;OPTION BANK 1
.alias R_BYT3            $4360    ;OPTION BANK 2
.alias R_CHN             $4380    ;READ A TO D CHANNEL
.alias R_RCVS            $4400    ;RECEIVE BYTE FROM SOUND BOARD
.alias W_XMTS            $4400    ;TRANSMIT BYTE TO SOUND BOARD
.alias R_STAS            $4401    ;SND STATUS
.alias EEBUF             $4500    ;256 byte buffer the EEROM is copied to and swapped with while it is recalled and checked. In ESB: the address is the NVRAM itself: the image is kept as whole bytes at EEROM, and EETST and EECMP compare it with the nibbles here
.alias NVRAM             $4500    ;POWER FAIL NON-VOLATILE RAM, 256.*4
.alias EEROMZ            $4600    ;End of the non-volatile RAM (limit of the EEROM copy and swap loops).
.alias NVRAMZ            $4600    ;End of the non-volatile RAM (limit of the self test's loops).
.alias VGGO              $4600    ;ANY WRITE RESTARTS AT VRAM
.alias VGSTOP            $4620    ;ANY WRITE SLAPS DOWN VG, UNCONTROLLED HALT
.alias WTCHDG            $4640    ;RESETS IF NOT HIT OFTEN - EVERY 8*4 IRQS
