.alias W_LED2            $4683    ;LED 2, D7=0 turns it on (Atari's comment is a ditto mark under W_LED1).
.alias W_BANK            $4684    ;D7=0==>ROOT, D7=1 ==> OVERLAY BANK
.alias P_IRND            $4685    ;CONTROL GENERATOR, 0 INITS,80 RUNS IT
.alias W_LED1            $4686    ;D7=0==>ON
.alias NVRRCL            $4687    ;NOVRAM RECALL LATCH, D7 HI RECALLS DATA, DATA NOT ACCESSABLE WHILE IN RECALL MODE
.alias NSTORE            $46A0    ;NOVRAM STORE, WRITE STROBE, TAKES 10 MS FOR COMPLETE STORE CYCLE
.alias W_CHN0            $46C0    ;CHANNEL 0 START
.alias W_CHN1            $46C1    ;CHANNEL 1 START
.alias W_RSTS            $46E0    ;RESET SOUND BOARD
.alias M_PCGO            $4700    ;PROGRAM COUNTER START ADDRESS AND GO
.alias M_QUO             $4700    ;Read: the divider's 16-bit quotient (M_QUOH, M_QUOL). With the numerator left at $0200 it is the reciprocal used for perspective.
.alias M_BIC             $4701    ;BLOCK INDEX COUNTER
.alias M_BICH            $4701    ;HI
.alias M_BICL            $4702    ;LO
.alias P_RND             $4703    ;RANDOM BYTE GENERATOR (3 MHZ, 24 BIT)
.alias P_RND1            $4703    ;RANDOM BYTE,1
.alias P_RND2            $4703    ;RANDOM BYTE,2
.alias M_DVD             $4704    ;Write: the divider's 16-bit denominator (M_DVDH, M_DVDL); writing the low byte starts the divide.
.alias M_DVN             $4706    ;Write: the divider's 16-bit numerator (M_DVNH, M_DVNL); normally left at $0200.

