.alias EEINDX            $4C1C    ;INDEX FOR OPTION SWITCHES IN NOVRAM
.alias NVTSTR            $4C1D    ;NVRAM TEST RESULTS
.alias NVADDR            $4C1E    ;NVRAM ERROR ADDRESS
.alias opt_mask          $4C20    ;option page: the field mask of the selected option - 1, 3, 7 or 15 by its size - which is also its highest value. opt_page_change shifts it to the field's bit position when the value is changed
