.alias ee_tmp            $4C2C    ;scratch byte of the accounting and option pages: the average game time while it is made into minutes and seconds, the option descriptor while EEOPT3 shifts it down
.alias TEMP2             $4C2D    ;Four more bytes of scratch: the second operand of the accounting sums.
