.alias temp_2            $4C33    ;third byte of TEMP
.alias temp_3            $4C34    ;fourth byte of TEMP
.alias TIMER             $4C35    ;RAM BASED TIME, GET TRANSFERED TO NOVRAM OCCAISIONALLY
.alias timer_2           $4C37    ;word: third and fourth bytes of TIMER, the RAM based time on
