.alias w1_active         $4C69    ;probot part: number of probot records in use, counted afresh every frame by probots_move on page 2. the part's last phase (wave1_end_exec) ends when it is 0
.alias w2_active_a       $4C6A    ;walker part: number of AT-ST records in use, counted afresh every frame by atst_move_all on page 1
.alias w2_active_b       $4C6B    ;walker part: number of AT-AT records in use, counted afresh every frame by atat_move_all on page 0
