.alias legs_bon_tmr      $4CDF    ;frames the legs bonus stays on screen: 20 from scr_legs_bonus, counted down by page 1 (P1_9D45) while it shows legs_bonus
.alias EEROM             $4D00    ;NVRAM under the name the accounting code uses; the four checksummed areas are laid out from here. In ESB: a RAM image of the NVRAM with one byte for every two nibbles, $4D00-$4D7F: area 0 the options backup $4D00-$4D03, area 1 the top ten high scores $4D04-$4D4A, area 2 the pot limits and the accounting $4D4B-$4D79, area 3 the options $4D7A-$4D7D, the last byte of each its checksum. ee_init builds it from the NVRAM and EECKSM writes an area back
.alias dup_opts1         $4D01    ;NVRAM image, area 0: backup copy of the game option byte OPTS1. the default is the option switch byte R_OPT2 with bits 0, 3 and 4 inverted and bit 7 set
.alias dup_opts2         $4D02    ;NVRAM image, area 0: backup copy of the third option byte ($4D7C, Star Wars' misc. options), 0 by default
.alias EECK0             $4D03    ;CHECKSUM FOR AREA 0 (Atari's name): one byte in ESB, the last of the four bytes of the options backup
.alias nv_hiscores       $4D04    ;70 bytes of the NVRAM image ($4D04-$4D49): the top ten high score entries, 3 initials and 4 BCD score bytes each, copied to and from INITLS
.alias POTSAV            $4D4B    ;POT VALUES
.alias potsav_1          $4D4C    ;second byte of POTSAV: the spread multiplier of the pitch pot (RHEOP+RHS_SP) saved at the end of a game
.alias potsav_2          $4D4D    ;third byte of POTSAV: the low limit of the yaw pot (RHEOY+RHS_LO)
.alias potsav_3          $4D4E    ;fourth byte of POTSAV: the spread multiplier of the yaw pot (RHEOY+RHS_SP)
.alias AMECH             $4D4F    ;AUX COIN COUNT
.alias LMECH             $4D52    ;LEFT COIN COUNT (Atari's name): 3 BCD bytes in the NVRAM image, between AMECH and RMECH
.alias lmech_1           $4D53    ;second byte of LMECH
.alias lmech_2           $4D54    ;third byte of LMECH
.alias RMECH             $4D55    ;RIGHT COIN COUNT
.alias rmech_1           $4D56    ;second byte of RMECH
.alias rmech_2           $4D57    ;third byte of RMECH
.alias GAMES             $4D58    ;NUMBER OF GAMES PLAYED (Atari's name): 3 BCD bytes in the NVRAM image, $4D58-$4D5A, after RMECH. EEACCT adds 1 at the end of a game, the accounting page shows it and divides the total game time by it. the one matched Star Wars line, LDX #GAMES-2, had put the name on the middle byte
.alias games_mid         $4D59    ;second byte of GAMES
.alias games_lo          $4D5A    ;last byte of the number of games played, the one EEACCT adds 1 to
.alias cont_games        $4D5B    ;NVRAM image: 3 BCD bytes, the number of games started from the continue offer, shown as ADD-A-COIN GAMES. EEACCT adds 1 when cont_used is set
.alias cont_games_1      $4D5C    ;second byte of cont_games
.alias cont_games_2      $4D5D    ;third byte of cont_games
.alias TTIME             $4D5E    ;TOTAL GAME TIMER
.alias ttime_1           $4D5F    ;second of the four BCD bytes of TTIME, the total game time in 4 second units
.alias ttime_2           $4D60    ;third byte of TTIME
.alias ttime_3           $4D61    ;fourth byte of TTIME
.alias TIMEON            $4D62    ;TOTAL TIME GAME ON
.alias timeon_2          $4D64    ;word: third and fourth bytes of TIMEON
.alias HISTOG            $4D66    ;GAME TIME HISTOGRAM
.alias hist_last         $4D77    ;last of the 18 one-byte BCD bins of HISTOG: games of 5:40 and longer. the other bins are 20 seconds wide
.alias high_wave         $4D78    ;NVRAM image: the highest wave reached in any game, BCD (Star Wars' ENDGAM). EEACCT raises it to wave_bcd, the accounting page shows it. it is the last data byte of area 2
.alias EECK2             $4D79    ;CHECKSUM FOR AREA 2 (Atari's name): one byte in ESB, after the accounting data
.alias OPTS0             $4D7A    ;COIN MODE OPTIONS SWITCHES
.alias OPTS1             $4D7B    ;GAME MODE OPTIONS (Atari's name), the second byte of option area 3 in the NVRAM image: bits 1-0 starting shields (2 to 5), bits 3-2 play difficulty, bits 5-4 Jedi-letter mode - with bit 5 set jedi_award gives the letters in the order J, E, D, I whatever part is played, with bit 4 set completing JEDI starts no force period - bit 6 music in attract, bit 7 set by the default. the option page changes the fields, the default is the option switch byte R_OPT2 with bits 0, 3 and 4 inverted
.alias EECK3             $4D7D    ;CHECKSUM FOR AREA 3 (Atari's name): one byte in ESB, after the three option bytes. ee_init compares it with EECK0
.alias RESETS            $4D7E    ;FLAGS FOR CLEARING AREAS
.alias ST_QU             $4D80    ;Star queues: STS_EQQ screen sectors of STS_IZQ bytes each. Shares the large temp area with BJ_PNT, LZPNT and EEBUF. In ESB: in the walker part page 0's tow cable view keeps its screen positions and flags in the first $21 bytes, $4D80-$4DA0 (cable_scrx on): the star view fills and empties the queues within its own call. bank 1's NVRAM code uses the address as the end of the image at EEROM
.alias cable_scrx        $4D80    ;word: screen x of the tow cable's centre, from cable_view on page 0. cable_draw_lines draws the two lines from this point. first of the walker part's tow cable temps $4D80-$4DA0, which lie over the start of the star queues ST_QU
