.alias cable_viewx       $4D84    ;word: the tow cable's centre as seen from the ship, x (distance ahead). kept by cable_view as the post-add input for the two ends
.alias cable_viewy       $4D86    ;word: the tow cable's centre as seen from the ship, y
.alias cable_viewz       $4D88    ;word: the tow cable's centre as seen from the ship, z
.alias cable_seen        $4D8A    ;nonzero when the tow cable's centre is in view this frame. cleared at the start of cable_view, tested by cable_draw_lines
.alias end1_scrx         $4D8B    ;word: screen x of the cable's first end, from cable_view_end1, where cable_draw_lines ends the first line
.alias end1_scry         $4D8D    ;word: screen y of the cable's first end
.alias end1_viewx        $4D8F    ;word: the cable's first end as seen from the ship, x. written by cable_view_end1 and read by nothing
.alias end1_viewy        $4D91    ;word: the cable's first end as seen from the ship, y. written and read by nothing
.alias end1_viewz        $4D93    ;word: the cable's first end as seen from the ship, z. written and read by nothing
.alias end1_seen         $4D95    ;nonzero when the cable's first end is in view this frame. cleared at the start of cable_view, tested by cable_draw_lines
.alias end2_scrx         $4D96    ;word: screen x of the cable's second end, from cable_view_end2
.alias end2_scry         $4D98    ;word: screen y of the cable's second end
.alias end2_viewx        $4D9A    ;word: the cable's second end as seen from the ship, x. written by cable_view_end2 and read by nothing
.alias end2_viewy        $4D9C    ;word: the cable's second end as seen from the ship, y. written and read by nothing
.alias end2_viewz        $4D9E    ;word: the cable's second end as seen from the ship, z. written and read by nothing
